import type { NextRequest } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
})

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { from, to } = parsed.data
  const supabase = await createClient()

  try {
    let bookingsQuery = supabase
      .from('bookings')
      .select('id, artist_id, price_cents, deposit_cents, tip_cents, status, scheduled_at, artists(profiles(full_name))')
      .eq('studio_id', auth.studioId)
      .in('status', ['completed', 'no_show'])

    if (from) bookingsQuery = bookingsQuery.gte('scheduled_at', from)
    if (to) bookingsQuery = bookingsQuery.lte('scheduled_at', to)

    const { data: bookings, error } = await bookingsQuery
    if (error) throw error

    // Aggregate per artist
    const artistMap = new Map<string, {
      artistId: string
      artistName: string
      revenue: number
      sessions: number
      noShows: number
      tips: number
    }>()

    for (const b of bookings ?? []) {
      if (!b.artist_id) continue
      const artistData = b.artists as unknown as { profiles: { full_name: string | null } | null } | null
      const name = artistData?.profiles?.full_name

      const existing = artistMap.get(b.artist_id) ?? {
        artistId: b.artist_id,
        artistName: (name as string | null | undefined) ?? 'Unknown',
        revenue: 0,
        sessions: 0,
        noShows: 0,
        tips: 0,
      }

      if (b.status === 'completed') {
        existing.revenue += (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
        existing.sessions++
        existing.tips += b.tip_cents ?? 0
      } else {
        existing.noShows++
      }

      artistMap.set(b.artist_id, existing)
    }

    const leaderboard = Array.from(artistMap.values())
      .map((a) => ({
        ...a,
        avgTipPct: a.revenue > 0 ? Math.round((a.tips / a.revenue) * 100) : 0,
        noShowRate: (a.sessions + a.noShows) > 0
          ? Math.round((a.noShows / (a.sessions + a.noShows)) * 100)
          : 0,
      }))
      .sort((a, b) => b.revenue - a.revenue)

    return Response.json({ leaderboard })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'artists report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

