import type { NextRequest } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface ArtistAccumulator {
  artistId: string
  artistName: string
  revenue: number
  sessions: number
  noShows: number
  tips: number
}

type BookingRow = {
  id: string
  artist_id: string | null
  price_cents: number | null
  deposit_cents: number | null
  tip_cents: number | null
  status: string
  scheduled_at: string | null
  artists: { profiles: { full_name: string | null } | null } | null
}

function aggregateLeaderboard(bookings: BookingRow[]) {
  const artistMap = new Map<string, ArtistAccumulator>()

  for (const b of bookings) {
    if (!b.artist_id) continue
    const artistData = b.artists
    const name = artistData?.profiles?.full_name

    const existing = artistMap.get(b.artist_id) ?? {
      artistId: b.artist_id,
      artistName: name ?? 'Unknown',
      revenue: 0,
      sessions: 0,
      noShows: 0,
      tips: 0,
    }

    if (b.status === 'completed') {
      existing.revenue += (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
      existing.sessions++
      existing.tips += b.tip_cents ?? 0
    } else if (b.status === 'no_show') {
      existing.noShows++
    }

    artistMap.set(b.artist_id, existing)
  }

  return Array.from(artistMap.values())
    .map((a) => ({
      artistId: a.artistId,
      name: a.artistName,
      sessions: a.sessions,
      revenueCents: a.revenue,
      avgSessionCents: a.sessions > 0 ? Math.round(a.revenue / a.sessions) : 0,
      noShows: a.noShows,
      noShowRate: (a.sessions + a.noShows) > 0
        ? Math.round((a.noShows / (a.sessions + a.noShows)) * 100)
        : 0,
      avgTipPct: a.revenue > 0 ? Math.round((a.tips / a.revenue) * 100) : 0,
    }))
    .sort((a, b) => b.revenueCents - a.revenueCents)
}

async function fetchLeaderboard(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from?: string,
  to?: string,
) {
  let q = supabase
    .from('bookings')
    .select('id, artist_id, price_cents, deposit_cents, tip_cents, status, scheduled_at, artists(profiles(full_name))')
    .eq('studio_id', studioId)
    .in('status', ['completed', 'no_show'])

  if (from) q = q.gte('scheduled_at', from)
  if (to) q = q.lte('scheduled_at', to)

  const { data, error } = await q
  if (error) throw error
  return aggregateLeaderboard((data ?? []) as BookingRow[])
}

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { compare } = parsed.data
  const rangeData = parseRange(req.nextUrl.searchParams)
  const { current } = rangeData
  const supabase = await createClient()

  try {
    if (compare === '1') {
      const prior = priorRange(current)
      const [currentLeaderboard, priorLeaderboard] = await Promise.all([
        fetchLeaderboard(supabase, auth.studioId, current.from, current.to),
        fetchLeaderboard(supabase, auth.studioId, prior.from, prior.to),
      ])
      return Response.json({ current: currentLeaderboard, prior: priorLeaderboard })
    }

    const leaderboard = await fetchLeaderboard(supabase, auth.studioId, current.from, current.to)
    return Response.json({ current: leaderboard })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'artists report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

