import type { NextRequest } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange, pickGroupBy, rangeDays } from '@/lib/analytics/range'
import { format } from 'date-fns'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

type BookingDetail = {
  id: string
  price_cents: number | null
  deposit_cents: number | null
  tip_cents: number | null
  status: string
  scheduled_at: string | null
  services: { name: string } | null
  artist_id: string | null
  artists: { profiles: { full_name: string | null } | null } | null
}

function formatPeriod(date: Date, groupBy: 'day' | 'week' | 'month'): string {
  if (groupBy === 'month') return format(date, 'MMM yyyy')
  if (groupBy === 'week') return format(date, 'MMM d')
  return format(date, 'MMM d')
}

function buildDetailBlock(
  artistId: string,
  artistName: string,
  bookings: BookingDetail[],
  groupBy: 'day' | 'week' | 'month',
) {
  let revenueCents = 0
  let sessions = 0
  let noShows = 0
  let tipsCents = 0

  const timelineMap = new Map<string, number>()
  const noShowMap = new Map<string, number>()
  const serviceMap = new Map<string, { name: string; count: number; revenueCents: number }>()

  for (const b of bookings) {
    const date = b.scheduled_at ? new Date(b.scheduled_at) : null
    const periodKey = date ? formatPeriod(date, groupBy) : 'Unknown'

    if (b.status === 'completed') {
      const rev = (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
      revenueCents += rev
      sessions++
      tipsCents += b.tip_cents ?? 0

      // Revenue timeline
      timelineMap.set(periodKey, (timelineMap.get(periodKey) ?? 0) + rev)

      // Top services
      const svcName = b.services?.name ?? 'Walk-in / Unscheduled'
      const svc = serviceMap.get(svcName) ?? { name: svcName, count: 0, revenueCents: 0 }
      svc.count++
      svc.revenueCents += rev
      serviceMap.set(svcName, svc)
    } else if (b.status === 'no_show') {
      noShows++
      noShowMap.set(periodKey, (noShowMap.get(periodKey) ?? 0) + 1)
    }
  }

  const noShowRate = (sessions + noShows) > 0
    ? Math.round((noShows / (sessions + noShows)) * 100)
    : 0

  const revenueTimeline = Array.from(timelineMap.entries()).map(([period, rev]) => ({
    period,
    revenueCents: rev,
  }))

  const noShowTimeline = Array.from(noShowMap.entries()).map(([period, count]) => ({
    period,
    count,
  }))

  const topServices = Array.from(serviceMap.values())
    .sort((a, b) => b.revenueCents - a.revenueCents)
    .slice(0, 5)

  return {
    artistId,
    name: artistName,
    totals: {
      revenueCents,
      sessions,
      avgSessionCents: sessions > 0 ? Math.round(revenueCents / sessions) : 0,
      noShows,
      noShowRate,
      tipsCents,
    },
    revenueTimeline,
    topServices,
    noShowTimeline,
  }
}

async function fetchArtistDetail(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  artistId: string,
  from: string,
  to: string,
  groupBy: 'day' | 'week' | 'month',
) {
  // Verify artist belongs to studio
  const { data: member, error: memberErr } = await supabase
    .from('studio_members')
    .select('id, profiles(full_name)')
    .eq('studio_id', studioId)
    .eq('user_id', artistId)
    .single()

  if (memberErr || !member) return null

  const memberData = member as { id: string; profiles: { full_name: string | null } | null }
  const artistName = memberData.profiles?.full_name ?? 'Unknown'

  const { data: bookings, error: bookErr } = await supabase
    .from('bookings')
    .select('id, price_cents, deposit_cents, tip_cents, status, scheduled_at, services(name), artist_id, artists(profiles(full_name))')
    .eq('studio_id', studioId)
    .eq('artist_id', artistId)
    .in('status', ['completed', 'no_show'])
    .gte('scheduled_at', from)
    .lte('scheduled_at', to)

  if (bookErr) throw bookErr

  return buildDetailBlock(artistId, artistName, (bookings ?? []) as BookingDetail[], groupBy)
}

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> },
) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const { id: artistId } = await params

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { compare } = parsed.data
  const rangeData = parseRange(req.nextUrl.searchParams)
  const { current } = rangeData
  const days = rangeDays(current)
  const groupBy = pickGroupBy(days)
  const supabase = await createClient()

  try {
    if (compare === '1') {
      const prior = priorRange(current)
      const [currentBlock, priorBlock] = await Promise.all([
        fetchArtistDetail(supabase, auth.studioId, artistId, current.from, current.to, groupBy),
        fetchArtistDetail(supabase, auth.studioId, artistId, prior.from, prior.to, groupBy),
      ])

      if (!currentBlock) return new Response('Artist not found', { status: 404 })

      return Response.json({ current: currentBlock, prior: priorBlock ?? undefined })
    }

    const currentBlock = await fetchArtistDetail(
      supabase,
      auth.studioId,
      artistId,
      current.from,
      current.to,
      groupBy,
    )

    if (!currentBlock) return new Response('Artist not found', { status: 404 })

    return Response.json({ current: currentBlock })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId, artistId }, 'artist detail report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

/**
 * Shared analytics types used by both API routes and client components.
 * Do NOT hand-edit lib/supabase/types.ts — these are analytics-layer types only.
 */

// ─── Artist Leaderboard ──────────────────────────────────────────────────────

export interface ArtistRow {
  artistId: string
  name: string
  sessions: number
  revenueCents: number
  avgSessionCents: number
  noShows: number
  noShowRate: number
  avgTipPct: number
}

// ─── Artist Drill-Down Detail ────────────────────────────────────────────────

export interface ArtistTotals {
  revenueCents: number
  sessions: number
  avgSessionCents: number
  noShows: number
  noShowRate: number
  tipsCents: number
}

export interface ArtistRevenuePoint {
  period: string
  revenueCents: number
}

export interface ArtistTopService {
  name: string
  count: number
  revenueCents: number
}

export interface ArtistNoShowPoint {
  period: string
  count: number
}

export interface ArtistDetailBlock {
  artistId: string
  name: string
  totals: ArtistTotals
  revenueTimeline: ArtistRevenuePoint[]
  topServices: ArtistTopService[]
  noShowTimeline: ArtistNoShowPoint[]
}

export interface ArtistDetailResponse {
  current: ArtistDetailBlock
  prior?: ArtistDetailBlock
}

export interface ArtistsLeaderboardResponse {
  current: ArtistRow[]
  prior?: ArtistRow[]
}

'use client'

import {
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
} from '@tanstack/react-table'
import { useState } from 'react'
import { ChevronUp, ChevronDown, ChevronsUpDown } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { cn } from '@/lib/utils'
import { formatCurrency } from '@/lib/utils'
import type { ArtistRow } from '@/lib/types/analytics'

interface ArtistLeaderboardTableProps {
  rows: ArtistRow[]
  onRowClick: (artistId: string) => void
}

function SortIcon({ state }: { state: false | 'asc' | 'desc' }) {
  if (state === 'asc') return <ChevronUp className="ml-1 h-3.5 w-3.5 text-[var(--color-stone)]" aria-hidden="true" />
  if (state === 'desc') return <ChevronDown className="ml-1 h-3.5 w-3.5 text-[var(--color-stone)]" aria-hidden="true" />
  return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 text-[var(--color-stone)]/40" aria-hidden="true" />
}

export function ArtistLeaderboardTable({ rows, onRowClick }: ArtistLeaderboardTableProps) {
  const [sorting, setSorting] = useState<SortingState>([
    { id: 'revenueCents', desc: true },
  ])

  const columns: ColumnDef<ArtistRow>[] = [
    {
      id: 'rank',
      header: '#',
      cell: ({ row }) => (
        <span className="tabular-nums text-xs font-semibold text-[var(--color-stone)]">
          {row.index + 1}
        </span>
      ),
      enableSorting: false,
      size: 36,
    },
    {
      accessorKey: 'name',
      header: 'Artist',
      cell: ({ getValue }) => (
        <span className="text-sm font-medium text-foreground">
          {getValue<string>()}
        </span>
      ),
      size: 180,
    },
    {
      accessorKey: 'sessions',
      header: 'Sessions',
      cell: ({ getValue }) => (
        <span className="tabular-nums text-sm text-foreground">{getValue<number>()}</span>
      ),
      size: 80,
    },
    {
      accessorKey: 'revenueCents',
      header: 'Revenue',
      cell: ({ getValue }) => (
        <span className="tabular-nums text-sm font-medium text-foreground">
          {formatCurrency(getValue<number>())}
        </span>
      ),
      size: 100,
    },
    {
      accessorKey: 'avgSessionCents',
      header: 'Avg Session',
      cell: ({ getValue }) => (
        <span className="tabular-nums text-sm text-foreground">
          {formatCurrency(getValue<number>())}
        </span>
      ),
      size: 100,
    },
    {
      accessorKey: 'noShowRate',
      header: 'No-show',
      cell: ({ getValue }) => {
        const rate = getValue<number>()
        return (
          <Badge
            variant={rate > 10 ? 'destructive' : 'outline'}
            className="tabular-nums text-xs"
          >
            {rate}%
          </Badge>
        )
      },
      size: 90,
    },
    {
      accessorKey: 'avgTipPct',
      header: 'Tip %',
      cell: ({ getValue }) => (
        <span className="tabular-nums text-sm text-[var(--color-stone)]">
          {getValue<number>()}%
        </span>
      ),
      size: 70,
    },
  ]

  const table = useReactTable({
    data: rows,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    // 3-state sort: asc → desc → none (back to default)
    sortDescFirst: true,
    enableMultiSort: false,
  })

  return (
    <div className="overflow-x-auto">
      <table
        className="w-full min-w-[600px] border-collapse text-left"
        aria-label="Artist leaderboard"
      >
        <thead className="sticky top-0 z-10 bg-[var(--color-bone)] border-b border-border">
          {table.getHeaderGroups().map((hg) => (
            <tr key={hg.id}>
              {hg.headers.map((header) => {
                const sortState = header.column.getIsSorted()
                const canSort = header.column.getCanSort()
                return (
                  <th
                    key={header.id}
                    className={cn(
                      'px-4 py-3 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)] whitespace-nowrap select-none',
                      canSort && 'cursor-pointer hover:text-foreground transition-colors',
                    )}
                    style={{ width: header.getSize() }}
                    onClick={canSort ? header.column.getToggleSortingHandler() : undefined}
                    aria-sort={
                      sortState === 'asc'
                        ? 'ascending'
                        : sortState === 'desc'
                          ? 'descending'
                          : 'none'
                    }
                  >
                    <span className="inline-flex items-center">
                      {flexRender(header.column.columnDef.header, header.getContext())}
                      {canSort && <SortIcon state={sortState} />}
                    </span>
                  </th>
                )
              })}
            </tr>
          ))}
        </thead>
        <tbody className="divide-y divide-border/50">
          {table.getRowModel().rows.map((row) => (
            <tr
              key={row.id}
              className="cursor-pointer transition-colors hover:bg-[var(--color-stone)]/5"
              onClick={() => onRowClick(row.original.artistId)}
              tabIndex={0}
              role="button"
              aria-label={`View details for ${row.original.name}`}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault()
                  onRowClick(row.original.artistId)
                }
              }}
            >
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="px-4 py-3.5 align-middle">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

/**
 * Returns the current sorted rows for CSV export.
 * Pass this to useExportCsv getRows so the export reflects active sort.
 */
export function getSortedArtistRows(table: ReturnType<typeof useReactTable<ArtistRow>>): ArtistRow[] {
  return table.getRowModel().rows.map((r) => r.original)
}

