function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

function formatDelta(delta: number | null): string | undefined {
  if (delta === null) return undefined
  const prefix = delta > 0 ? '+' : ''
  return `${prefix}${delta.toFixed(1)}%`
}

function KpiStrip({
  current,
  prior,
}: {
  current: ArtistDetailBlock
  prior?: ArtistDetailBlock
}) {
  const revDelta = computeDelta(current.totals.revenueCents, prior?.totals.revenueCents ?? null)
  const sessionsDelta = computeDelta(current.totals.sessions, prior?.totals.sessions ?? null)
  const avgDelta = computeDelta(current.totals.avgSessionCents, prior?.totals.avgSessionCents ?? null)
  const noShowDelta = computeDelta(current.totals.noShowRate, prior?.totals.noShowRate ?? null)

  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      <KpiCard
        label="Revenue"
        value={formatCurrency(current.totals.revenueCents)}
        delta={formatDelta(revDelta)}
        trend={trendOf(revDelta)}
        subtextLabel={prior ? 'vs prior' : undefined}
        index={0}
        hoverVariant="none"
        accentVar="var(--color-primary)"
      />
      <KpiCard
        label="Sessions"
        value={current.totals.sessions}
        delta={formatDelta(sessionsDelta)}
        trend={trendOf(sessionsDelta)}
        subtextLabel={prior ? 'vs prior' : undefined}
        index={1}
        hoverVariant="none"
        accentVar="var(--color-primary)"
      />
      <KpiCard
        label="Avg Session"
        value={formatCurrency(current.totals.avgSessionCents)}
        delta={formatDelta(avgDelta)}
        trend={trendOf(avgDelta)}
        subtextLabel={prior ? 'vs prior' : undefined}
        index={2}
        hoverVariant="none"
        accentVar="var(--color-primary)"
      />
      <KpiCard
        label="No-show Rate"
        value={`${current.totals.noShowRate}%`}
        delta={formatDelta(noShowDelta)}
        trend={trendOf(noShowDelta)}
        invertTrend
        subtextLabel={prior ? 'vs prior' : undefined}
        index={3}
        hoverVariant="none"
        accentVar={current.totals.noShowRate > 10 ? 'var(--color-destructive)' : 'var(--color-stone)'}
      />
    </div>
  )
}

