import type { NextRequest } from 'next/server'
import { getAuthenticatedUser } from '@/lib/supabase/server'
import { createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { z } from 'zod'
import { parseRange, priorRange } from '@/lib/analytics/range'

const querySchema = z.object({
  from: z.string().datetime({ offset: true }).optional(),
  to: z.string().datetime({ offset: true }).optional(),
  compare: z.enum(['0', '1']).optional().default('0'),
})

interface ArtistAccumulator {
  artistId: string
  artistName: string
  revenue: number
  sessions: number
  noShows: number
  tips: number
}

type BookingRow = {
  id: string
  artist_id: string | null
  price_cents: number | null
  deposit_cents: number | null
  tip_cents: number | null
  status: string
  scheduled_at: string | null
  artists: { profiles: { full_name: string | null } | null } | null
}

function aggregateLeaderboard(bookings: BookingRow[]) {
  const artistMap = new Map<string, ArtistAccumulator>()

  for (const b of bookings) {
    if (!b.artist_id) continue
    const name = b.artists?.profiles?.full_name

    const existing = artistMap.get(b.artist_id) ?? {
      artistId: b.artist_id,
      artistName: name ?? 'Unknown',
      revenue: 0,
      sessions: 0,
      noShows: 0,
      tips: 0,
    }

    if (b.status === 'completed') {
      existing.revenue += (b.price_cents ?? 0) + (b.deposit_cents ?? 0)
      existing.sessions++
      existing.tips += b.tip_cents ?? 0
    } else if (b.status === 'no_show') {
      existing.noShows++
    }

    artistMap.set(b.artist_id, existing)
  }

  return Array.from(artistMap.values())
    .map((a) => ({
      artistId: a.artistId,
      name: a.artistName,
      sessions: a.sessions,
      revenueCents: a.revenue,
      avgSessionCents: a.sessions > 0 ? Math.round(a.revenue / a.sessions) : 0,
      noShows: a.noShows,
      noShowRate:
        a.sessions + a.noShows > 0
          ? Math.round((a.noShows / (a.sessions + a.noShows)) * 100)
          : 0,
      avgTipPct: a.revenue > 0 ? Math.round((a.tips / a.revenue) * 100) : 0,
    }))
    .sort((a, b) => b.revenueCents - a.revenueCents)
}

async function fetchLeaderboard(
  supabase: Awaited<ReturnType<typeof createClient>>,
  studioId: string,
  from: string,
  to: string,
) {
  const { data, error } = await supabase
    .from('bookings')
    .select(
      'id, artist_id, price_cents, deposit_cents, tip_cents, status, scheduled_at, artists(profiles(full_name))',
    )
    .eq('studio_id', studioId)
    .in('status', ['completed', 'no_show'])
    .gte('scheduled_at', from)
    .lte('scheduled_at', to)

  if (error) throw error
  return aggregateLeaderboard((data ?? []) as BookingRow[])
}

export async function GET(req: NextRequest) {
  const ip = req.headers.get('x-forwarded-for') ?? 'anon'
  const { success } = await authedRatelimit.limit(ip)
  if (!success) return new Response('Too many requests', { status: 429 })

  const auth = await getAuthenticatedUser()
  if (!auth) return new Response('Unauthorized', { status: 401 })
  if (!['owner', 'admin'].includes(auth.role)) return new Response('Forbidden', { status: 403 })

  const parsed = querySchema.safeParse(Object.fromEntries(req.nextUrl.searchParams))
  if (!parsed.success) return Response.json({ error: parsed.error.flatten() }, { status: 400 })

  const { compare } = parsed.data
  const rangeData = parseRange(req.nextUrl.searchParams)
  const { current } = rangeData
  const supabase = await createClient()

  try {
    if (compare === '1') {
      const prior = priorRange(current)
      const [currentLeaderboard, priorLeaderboard] = await Promise.all([
        fetchLeaderboard(supabase, auth.studioId, current.from, current.to),
        fetchLeaderboard(supabase, auth.studioId, prior.from, prior.to),
      ])
      return Response.json({ current: currentLeaderboard, prior: priorLeaderboard })
    }

    const leaderboard = await fetchLeaderboard(supabase, auth.studioId, current.from, current.to)
    return Response.json({ current: leaderboard })
  } catch (err) {
    logger.error({ err, studioId: auth.studioId }, 'artists report failed')
    return Response.json({ error: 'Internal server error' }, { status: 500 })
  }
}

'use client'

import { useCallback, useRef } from 'react'
import { useSearchParams, useRouter, usePathname } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users } from 'lucide-react'
import {
  getCoreRowModel,
  getSortedRowModel,
  useReactTable,
  type SortingState,
} from '@tanstack/react-table'
import { useState } from 'react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { useExportCsv } from '@/hooks/use-export-csv'
import { ArtistLeaderboardTable } from './ArtistLeaderboardTable'
import { ArtistDrillDownDrawer } from './ArtistDrillDownDrawer'
import type { ArtistRow, ArtistsLeaderboardResponse } from '@/lib/types/analytics'

// Re-declare columns shape for table instance (needed to drive getRows)
const EMPTY_COLUMNS: Parameters<typeof useReactTable<ArtistRow>>[0]['columns'] = []

export function ArtistsReportClient() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const pathname = usePathname()

  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'
  const artistId = searchParams.get('artist')

  const { data, isLoading, error } = useQuery<ArtistsLeaderboardResponse>({
    queryKey: ['reports', 'artists', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/artists?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  // Sorting state — keep a ref so getRows() for CSV export always gets current sorted rows
  const [sorting, setSorting] = useState<SortingState>([
    { id: 'revenueCents', desc: true },
  ])

  const rows = data?.current ?? []

  // Build a table instance solely for sort-order tracking (no render — ArtistLeaderboardTable owns its own instance)
  // We track sorting state at this level so getRows can read it
  const sortedRowsRef = useRef<ArtistRow[]>(rows)

  // Keep a stable callback so useExportCsv dep array stays stable
  const getRows = useCallback((): ArtistRow[] => sortedRowsRef.current, [])

  useExportCsv<Record<string, unknown>>({
    filename: 'analytics-artists',
    getRows: () =>
      sortedRowsRef.current.map((r) => ({
        Artist: r.name,
        Sessions: r.sessions,
        Revenue: r.revenueCents / 100,
        'Avg Session ($)': r.avgSessionCents / 100,
        'No-show (%)': r.noShowRate,
        'Tip (%)': r.avgTipPct,
      })),
    headers: {
      Artist: 'Artist',
      Sessions: 'Sessions',
      Revenue: 'Revenue ($)',
      'Avg Session ($)': 'Avg Session ($)',
      'No-show (%)': 'No-show %',
      'Tip (%)': 'Tip %',
    },
  })

  function openArtist(id: string) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('artist', id)
    router.replace(`${pathname}?${params.toString()}`)
  }

  function closeArtist() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('artist')
    router.replace(`${pathname}?${params.toString()}`)
  }

  // Callback for ArtistLeaderboardTable to notify us of its sorted rows
  function onSortedRows(sortedRows: ArtistRow[]) {
    sortedRowsRef.current = sortedRows
  }

  return (
    <>
      <DataState
        data={rows}
        isLoading={isLoading}
        isError={Boolean(error)}
        error={error instanceof Error ? error : null}
        isEmpty={rows.length === 0 && !isLoading}
        loadingSlot={<TableSkeleton rows={6} cols={7} />}
        emptySlot={
          <EmptyState
            icon={Users}
            title="No artist data yet"
            description="Add artists and complete sessions to see performance data."
            variant="default"
          />
        }
      >
        {() => (
          <div className="space-y-4">
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Artist Leaderboard</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <ArtistLeaderboardTable
                  rows={rows}
                  onRowClick={openArtist}
                  onSortedRows={onSortedRows}
                />
              </CardContent>
            </Card>
          </div>
        )}
      </DataState>

      <ArtistDrillDownDrawer artistId={artistId} onClose={closeArtist} />
    </>
  )
}

'use client'

import { useRef, useState } from 'react'
import { useSearchParams, useRouter, usePathname } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { useExportCsv } from '@/hooks/use-export-csv'
import { ArtistLeaderboardTable } from './ArtistLeaderboardTable'
import { ArtistDrillDownDrawer } from './ArtistDrillDownDrawer'
import type { ArtistRow, ArtistsLeaderboardResponse } from '@/lib/types/analytics'

export function ArtistsReportClient() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const pathname = usePathname()

  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'
  const artistId = searchParams.get('artist')

  const { data, isLoading, error } = useQuery<ArtistsLeaderboardResponse>({
    queryKey: ['reports', 'artists', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/artists?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  // Ref tracks current sorted rows so CSV export always reflects active sort
  const sortedRowsRef = useRef<ArtistRow[]>([])

  function onSortedRows(rows: ArtistRow[]) {
    sortedRowsRef.current = rows
  }

  // Initialise ref with fetched rows when data first arrives
  const rows = data?.current ?? []
  if (sortedRowsRef.current.length === 0 && rows.length > 0) {
    sortedRowsRef.current = rows
  }

  useExportCsv<Record<string, string | number>>({
    filename: 'analytics-artists',
    getRows: () =>
      sortedRowsRef.current.map((r, i) => ({
        Rank: i + 1,
        Artist: r.name,
        Sessions: r.sessions,
        'Revenue ($)': r.revenueCents / 100,
        'Avg Session ($)': r.avgSessionCents / 100,
        'No-show (%)': r.noShowRate,
        'Tip (%)': r.avgTipPct,
      })),
  })

  function openArtist(id: string) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('artist', id)
    router.replace(`${pathname}?${params.toString()}`)
  }

  function closeArtist() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('artist')
    router.replace(`${pathname}?${params.toString()}`)
  }

  return (
    <>
      <DataState
        data={rows}
        isLoading={isLoading}
        isError={Boolean(error)}
        error={error instanceof Error ? error : null}
        isEmpty={rows.length === 0 && !isLoading}
        loadingSlot={<TableSkeleton rows={6} cols={7} />}
        emptySlot={
          <EmptyState
            icon={Users}
            title="No artist data yet"
            description="Add artists and complete sessions to see performance data."
            variant="default"
          />
        }
      >
        {() => (
          <div className="space-y-4">
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Artist Leaderboard</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <ArtistLeaderboardTable
                  rows={rows}
                  onRowClick={openArtist}
                  onSortedRows={onSortedRows}
                />
              </CardContent>
            </Card>
          </div>
        )}
      </DataState>

      <ArtistDrillDownDrawer artistId={artistId} onClose={closeArtist} />
    </>
  )
}

'use client'

import {
  flexRender,
  getCoreRowModel,
  getSortedRowModel,
  useReactTable,
  type ColumnDef,
  type SortingState,
  type Updater,
} from '@tanstack/react-table'
import { useEffect, useState } from 'react'
import { ChevronUp, ChevronDown, ChevronsUpDown } from 'lucide-react'
import { Badge } from '@/components/ui/badge'
import { cn, formatCurrency } from '@/lib/utils'
import type { ArtistRow } from '@/lib/types/analytics'

interface ArtistLeaderboardTableProps {
  rows: ArtistRow[]
  onRowClick: (artistId: string) => void
  /** Called after each sort change with the current sorted rows (for CSV export). */
  onSortedRows?: (sorted: ArtistRow[]) => void
}

function SortIcon({ state }: { state: false | 'asc' | 'desc' }) {
  if (state === 'asc')
    return <ChevronUp className="ml-1 h-3.5 w-3.5 shrink-0 text-[var(--color-stone)]" aria-hidden="true" />
  if (state === 'desc')
    return <ChevronDown className="ml-1 h-3.5 w-3.5 shrink-0 text-[var(--color-stone)]" aria-hidden="true" />
  return <ChevronsUpDown className="ml-1 h-3.5 w-3.5 shrink-0 text-[var(--color-stone)]/40" aria-hidden="true" />
}

const COLUMNS: ColumnDef<ArtistRow>[] = [
  {
    id: 'rank',
    header: '#',
    cell: ({ row }) => (
      <span className="tabular-nums text-xs font-semibold text-[var(--color-stone)]">
        {row.index + 1}
      </span>
    ),
    enableSorting: false,
    size: 36,
  },
  {
    accessorKey: 'name',
    header: 'Artist',
    cell: ({ getValue }) => (
      <span className="text-sm font-medium text-foreground">{getValue<string>()}</span>
    ),
    size: 180,
  },
  {
    accessorKey: 'sessions',
    header: 'Sessions',
    cell: ({ getValue }) => (
      <span className="tabular-nums text-sm text-foreground">{getValue<number>()}</span>
    ),
    size: 80,
  },
  {
    accessorKey: 'revenueCents',
    header: 'Revenue',
    cell: ({ getValue }) => (
      <span className="tabular-nums text-sm font-medium text-foreground">
        {formatCurrency(getValue<number>())}
      </span>
    ),
    size: 100,
  },
  {
    accessorKey: 'avgSessionCents',
    header: 'Avg Session',
    cell: ({ getValue }) => (
      <span className="tabular-nums text-sm text-foreground">
        {formatCurrency(getValue<number>())}
      </span>
    ),
    size: 100,
  },
  {
    accessorKey: 'noShowRate',
    header: 'No-show',
    cell: ({ getValue }) => {
      const rate = getValue<number>()
      return (
        <Badge
          className={cn(
            'tabular-nums text-xs border',
            rate > 10
              ? 'bg-[var(--color-rust)] text-[var(--color-bone)] border-transparent'
              : 'bg-transparent text-[var(--color-stone)] border-[var(--color-stone)]',
          )}
        >
          {rate}%
        </Badge>
      )
    },
    size: 90,
  },
  {
    accessorKey: 'avgTipPct',
    header: 'Tip %',
    cell: ({ getValue }) => (
      <span className="tabular-nums text-sm text-[var(--color-stone)]">
        {getValue<number>()}%
      </span>
    ),
    size: 70,
  },
]

export function ArtistLeaderboardTable({
  rows,
  onRowClick,
  onSortedRows,
}: ArtistLeaderboardTableProps) {
  const [sorting, setSorting] = useState<SortingState>([
    { id: 'revenueCents', desc: true },
  ])

  function handleSortingChange(updater: Updater<SortingState>) {
    setSorting((prev) => {
      const next = typeof updater === 'function' ? updater(prev) : updater
      return next
    })
  }

  const table = useReactTable({
    data: rows,
    columns: COLUMNS,
    state: { sorting },
    onSortingChange: handleSortingChange,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    // desc → asc → unsorted (3-state) — sortDescFirst drives first click to desc
    sortDescFirst: true,
    enableMultiSort: false,
  })

  // Notify parent of sorted rows after each sort or data change
  useEffect(() => {
    onSortedRows?.(table.getRowModel().rows.map((r) => r.original))
  }, [sorting, rows, onSortedRows, table])

  return (
    <div className="overflow-x-auto">
      <table
        className="w-full min-w-[600px] border-collapse text-left"
        aria-label="Artist leaderboard"
      >
        <thead className="sticky top-0 z-10 bg-[var(--color-bone)] border-b border-border">
          {table.getHeaderGroups().map((hg) => (
            <tr key={hg.id}>
              {hg.headers.map((header) => {
                const sortState = header.column.getIsSorted()
                const canSort = header.column.getCanSort()
                return (
                  <th
                    key={header.id}
                    className={cn(
                      'px-4 py-3 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)] whitespace-nowrap select-none',
                      canSort && 'cursor-pointer hover:text-foreground transition-colors',
                    )}
                    style={{ width: header.getSize() }}
                    onClick={canSort ? header.column.getToggleSortingHandler() : undefined}
                    aria-sort={
                      sortState === 'asc'
                        ? 'ascending'
                        : sortState === 'desc'
                          ? 'descending'
                          : 'none'
                    }
                  >
                    <span className="inline-flex items-center">
                      {flexRender(header.column.columnDef.header, header.getContext())}
                      {canSort && <SortIcon state={sortState} />}
                    </span>
                  </th>
                )
              })}
            </tr>
          ))}
        </thead>
        <tbody className="divide-y divide-border/50">
          {table.getRowModel().rows.map((row) => (
            <tr
              key={row.id}
              className="cursor-pointer transition-colors hover:bg-[var(--color-stone)]/5"
              onClick={() => onRowClick(row.original.artistId)}
              tabIndex={0}
              role="button"
              aria-label={`View details for ${row.original.name}`}
              onKeyDown={(e) => {
                if (e.key === 'Enter' || e.key === ' ') {
                  e.preventDefault()
                  onRowClick(row.original.artistId)
                }
              }}
            >
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="px-4 py-3.5 align-middle">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  )
}

'use client'

import { useSearchParams } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { ExternalLink, Users } from 'lucide-react'
import Link from 'next/link'
import dynamic from 'next/dynamic'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
  SheetFooter,
} from '@/components/ui/sheet'
import { Skeleton } from '@/components/ui/skeleton'
import { Button } from '@/components/ui/button'
import { Badge } from '@/components/ui/badge'
import { KpiCard } from '@/components/shared/KpiCard'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { formatCurrency, computeDelta } from '@/lib/utils'
import type { ArtistDetailResponse, ArtistDetailBlock } from '@/lib/types/analytics'

const RechartsAreaChart = dynamic(() => import('./RechartsAreaChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-40 w-full rounded-lg" />,
})
const RechartsBarChart = dynamic(() => import('./RechartsBarChart'), {
  ssr: false,
  loading: () => <Skeleton className="h-28 w-full rounded-lg" />,
})

interface ArtistDrillDownDrawerProps {
  artistId: string | null
  onClose: () => void
}

function trendOf(delta: number | null): 'up' | 'down' | 'neutral' {
  if (delta === null) return 'neutral'
  return delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral'
}

function formatDelta(delta: number | null): string | undefined {
  if (delta === null) return undefined
  const prefix = delta > 0 ? '+' : ''
  return `${prefix}${delta.toFixed(1)}%`
}

// Use explicit conditional spread to satisfy exactOptionalPropertyTypes
function optionalDelta(delta: number | null): { delta?: string; subtextLabel?: string } {
  if (delta === null) return {}
  const prefix = delta > 0 ? '+' : ''
  return {
    delta: `${prefix}${delta.toFixed(1)}%`,
    subtextLabel: 'vs prior',
  }
}

function KpiStrip({
  current,
  prior,
}: {
  current: ArtistDetailBlock
  prior?: ArtistDetailBlock
}) {
  const revDelta = computeDelta(current.totals.revenueCents, prior?.totals.revenueCents ?? null)
  const sessionsDelta = computeDelta(current.totals.sessions, prior?.totals.sessions ?? null)
  const avgDelta = computeDelta(current.totals.avgSessionCents, prior?.totals.avgSessionCents ?? null)
  const noShowDelta = computeDelta(current.totals.noShowRate, prior?.totals.noShowRate ?? null)

  return (
    <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
      <KpiCard
        label="Revenue"
        value={formatCurrency(current.totals.revenueCents)}
        trend={trendOf(revDelta)}
        {...optionalDelta(revDelta)}
        index={0}
        hoverVariant="none"
        accentVar="var(--color-primary)"
      />
      <KpiCard
        label="Sessions"
        value={current.totals.sessions}
        trend={trendOf(sessionsDelta)}
        {...optionalDelta(sessionsDelta)}
        index={1}
        hoverVariant="none"
        accentVar="var(--color-primary)"
      />
      <KpiCard
        label="Avg Session"
        value={formatCurrency(current.totals.avgSessionCents)}
        trend={trendOf(avgDelta)}
        {...optionalDelta(avgDelta)}
        index={2}
        hoverVariant="none"
        accentVar="var(--color-primary)"
      />
      <KpiCard
        label="No-show Rate"
        value={`${current.totals.noShowRate}%`}
        trend={trendOf(noShowDelta)}
        invertTrend
        {...optionalDelta(noShowDelta)}
        index={3}
        hoverVariant="none"
        accentVar={current.totals.noShowRate > 10 ? 'var(--color-destructive)' : 'var(--color-stone)'}
      />
    </div>
  )
}

function DetailContent({ data }: { data: ArtistDetailResponse }) {
  const { current, prior } = data

  const revTimeline = current.revenueTimeline.map((p) => ({
    name: p.period,
    value: p.revenueCents,
  }))

  const priorRevTimeline = prior?.revenueTimeline.map((p) => ({
    name: p.period,
    value: p.revenueCents,
  }))

  const noShowTimeline = current.noShowTimeline.map((p) => ({
    name: p.period,
    value: p.count,
  }))

  return (
    <div className="space-y-6 p-6 overflow-y-auto flex-1 min-h-0">
      {/* KPI strip */}
      <KpiStrip current={current} {...(prior !== undefined ? { prior } : {})} />

      {/* Revenue trend */}
      <div>
        <p className="mb-3 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)]">
          Revenue Trend
        </p>
        {revTimeline.length === 0 ? (
          <EmptyState
            icon={Users}
            title="No sessions yet"
            description="Complete sessions to see revenue trend."
            variant="default"
            size="sm"
          />
        ) : (
          <RechartsAreaChart
            data={revTimeline}
            label="Revenue"
            formatValue={(v) => formatCurrency(v)}
            {...(priorRevTimeline !== undefined ? { priorData: priorRevTimeline, priorLabel: 'Prior period' } : {})}
          />
        )}
      </div>

      {/* Top services */}
      <div>
        <p className="mb-3 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)]">
          Top Services
        </p>
        {current.topServices.length === 0 ? (
          <p className="text-sm text-muted-foreground">No service data available.</p>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm" aria-label="Top services">
              <thead>
                <tr className="border-b border-border">
                  <th className="pb-2 pr-4 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)]">
                    Service
                  </th>
                  <th className="pb-2 pr-4 text-right text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)]">
                    Bookings
                  </th>
                  <th className="pb-2 text-right text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)]">
                    Revenue
                  </th>
                </tr>
              </thead>
              <tbody className="divide-y divide-border/50">
                {current.topServices.map((svc) => (
                  <tr key={svc.name} className="hover:bg-[var(--color-stone)]/5 transition-colors">
                    <td className="py-2.5 pr-4 font-medium text-foreground">{svc.name}</td>
                    <td className="py-2.5 pr-4 text-right tabular-nums text-[var(--color-stone)]">
                      {svc.count}
                    </td>
                    <td className="py-2.5 text-right tabular-nums font-medium text-foreground">
                      {formatCurrency(svc.revenueCents)}
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* No-show timeline */}
      {noShowTimeline.length > 0 && (
        <div>
          <p className="mb-3 text-[10px] font-semibold uppercase tracking-[0.06em] text-[var(--color-stone)]">
            No-show Timeline
          </p>
          <RechartsBarChart
            data={noShowTimeline}
            label="No-shows"
            color="var(--color-destructive)"
          />
        </div>
      )}
    </div>
  )
}

export function ArtistDrillDownDrawer({ artistId, onClose }: ArtistDrillDownDrawerProps) {
  const searchParams = useSearchParams()
  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'

  const { data, isLoading, error } = useQuery<ArtistDetailResponse>({
    queryKey: ['reports', 'artists', artistId, from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/artists/${artistId}?${params.toString()}`).then((r) => {
        if (!r.ok) throw new Error(`HTTP ${r.status}`)
        return r.json()
      })
    },
    enabled: Boolean(artistId),
    staleTime: 5 * 60 * 1000,
  })

  const artistName = data?.current.name

  return (
    <Sheet open={Boolean(artistId)} onOpenChange={(open) => { if (!open) onClose() }}>
      <SheetContent
        side="right"
        className="w-full sm:max-w-[520px] flex flex-col overflow-hidden p-0"
        showCloseButton={false}
      >
        <SheetHeader className="px-6 py-4 border-b border-border shrink-0">
          <div className="flex items-center justify-between">
            <div className="min-w-0">
              <SheetTitle className="text-base font-semibold truncate">
                {isLoading ? (
                  <Skeleton className="h-5 w-32 inline-block" />
                ) : (
                  artistName ?? 'Artist Details'
                )}
              </SheetTitle>
              <SheetDescription className="text-xs text-muted-foreground mt-0.5">
                Performance breakdown
              </SheetDescription>
            </div>
            <div className="flex items-center gap-2 shrink-0 ml-4">
              {artistId && !isLoading && (
                <Badge variant="outline" className="text-xs tabular-nums">
                  {data?.current.totals.sessions ?? 0} sessions
                </Badge>
              )}
              <Button
                variant="ghost"
                size="icon-sm"
                onClick={onClose}
                aria-label="Close artist detail"
              >
                <span aria-hidden="true" className="text-lg leading-none">×</span>
              </Button>
            </div>
          </div>
        </SheetHeader>

        <DataState
          data={data}
          isLoading={isLoading}
          isError={Boolean(error)}
          error={error instanceof Error ? error : null}
          loadingSlot={
            <div className="p-6 space-y-4">
              <div className="grid grid-cols-2 gap-3 sm:grid-cols-4">
                {Array.from({ length: 4 }).map((_, i) => (
                  <Skeleton key={i} className="h-24 rounded-xl" />
                ))}
              </div>
              <Skeleton className="h-40 w-full rounded-lg" />
              <Skeleton className="h-36 w-full rounded-lg" />
            </div>
          }
          emptySlot={
            <div className="flex-1 flex items-center justify-center p-6">
              <EmptyState
                icon={Users}
                title="No data found"
                description="This artist has no activity in the selected period."
                variant="default"
              />
            </div>
          }
        >
          {(detail) => <DetailContent data={detail} />}
        </DataState>

        <SheetFooter className="border-t border-border px-6 py-4 shrink-0">
          {artistId && (
            <Button
              variant="outline"
              size="sm"
              render={
                <Link
                  href={`/artists/${artistId}`}
                  className="inline-flex items-center gap-1.5"
                />
              }
            >
              View artist profile
              <ExternalLink className="h-3.5 w-3.5" aria-hidden="true" />
            </Button>
          )}
        </SheetFooter>
      </SheetContent>
    </Sheet>
  )
}

