'use client'

import { useRef } from 'react'
import { useSearchParams, useRouter, usePathname } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Users } from 'lucide-react'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { DataState } from '@/components/shared/DataState'
import { EmptyState } from '@/components/shared/EmptyState'
import { TableSkeleton } from '@/components/skeletons'
import { useExportCsv } from '@/hooks/use-export-csv'
import { ArtistLeaderboardTable } from './ArtistLeaderboardTable'
import { ArtistDrillDownDrawer } from './ArtistDrillDownDrawer'
import type { ArtistRow, ArtistsLeaderboardResponse } from '@/lib/types/analytics'

export function ArtistsReportClient() {
  const searchParams = useSearchParams()
  const router = useRouter()
  const pathname = usePathname()

  const from = searchParams.get('from') ?? ''
  const to = searchParams.get('to') ?? ''
  const compare = searchParams.get('compare') ?? '0'
  const artistId = searchParams.get('artist')

  const { data, isLoading, error } = useQuery<ArtistsLeaderboardResponse>({
    queryKey: ['reports', 'artists', from, to, compare],
    queryFn: () => {
      const params = new URLSearchParams()
      if (from) params.set('from', from)
      if (to) params.set('to', to)
      if (compare === '1') params.set('compare', '1')
      return fetch(`/api/reports/artists?${params.toString()}`).then((r) => r.json())
    },
    staleTime: 5 * 60 * 1000,
  })

  // Ref tracks current sorted rows so CSV export always reflects active sort order
  const sortedRowsRef = useRef<ArtistRow[]>([])

  function onSortedRows(rows: ArtistRow[]) {
    sortedRowsRef.current = rows
  }

  // Seed ref with fetched rows on first load
  const rows = data?.current ?? []
  if (sortedRowsRef.current.length === 0 && rows.length > 0) {
    sortedRowsRef.current = rows
  }

  useExportCsv<Record<string, string | number>>({
    filename: 'analytics-artists',
    getRows: () =>
      sortedRowsRef.current.map((r, i) => ({
        Rank: i + 1,
        Artist: r.name,
        Sessions: r.sessions,
        'Revenue ($)': r.revenueCents / 100,
        'Avg Session ($)': r.avgSessionCents / 100,
        'No-show (%)': r.noShowRate,
        'Tip (%)': r.avgTipPct,
      })),
  })

  function openArtist(id: string) {
    const params = new URLSearchParams(searchParams.toString())
    params.set('artist', id)
    router.replace(`${pathname}?${params.toString()}`)
  }

  function closeArtist() {
    const params = new URLSearchParams(searchParams.toString())
    params.delete('artist')
    router.replace(`${pathname}?${params.toString()}`)
  }

  return (
    <>
      <DataState
        data={rows}
        isLoading={isLoading}
        isError={Boolean(error)}
        error={error instanceof Error ? error : null}
        isEmpty={rows.length === 0 && !isLoading}
        loadingSlot={<TableSkeleton rows={6} cols={7} />}
        emptySlot={
          <EmptyState
            icon={Users}
            title="No artist data yet"
            description="Add artists and complete sessions to see performance data."
            variant="default"
          />
        }
      >
        {() => (
          <div className="space-y-4">
            <Card className="border-border/50 shadow-[var(--shadow-card)]">
              <CardHeader>
                <CardTitle className="text-sm font-medium">Artist Leaderboard</CardTitle>
              </CardHeader>
              <CardContent className="p-0">
                <ArtistLeaderboardTable
                  rows={rows}
                  onRowClick={openArtist}
                  onSortedRows={onSortedRows}
                />
              </CardContent>
            </Card>
          </div>
        )}
      </DataState>

      <ArtistDrillDownDrawer artistId={artistId} onClose={closeArtist} />
    </>
  )
}
